import{_ as a,o as r,c as t,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Team board: quick guide","description":"Open the Chainy board. Sign in with your individual username (sherwin, christian, luis, sean, or miguel). The temporary first-use password is 123. Change it to your own privat","frontmatter":{"title":"Team board: quick guide","description":"Open the Chainy board. Sign in with your individual username (sherwin, christian, luis, sean, or miguel). The temporary first-use password is 123. Change it to your own privat","source":"docs/team-board-guide.md","category":"Other documents","sourceUpdated":"2026-11-11T13:03:58+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/team-board-guide.md","filePath":"content/docs/team-board-guide.md"}'),i={name:"content/docs/team-board-guide.md"};function n(s,e,d,c,h,l){return r(),t("div",null,[...e[0]||(e[0]=[o('<div><h1 id="team-board-quick-guide">Team board: quick guide<a class="header-anchor" href="#team-board-quick-guide" aria-label="Link to this section">​</a></h1><p>Open the <a href="https://owenlim225.github.io/Chainy-Docs/board/">Chainy board</a>. Sign in with your individual username (<code>sherwin</code>, <code>christian</code>, <code>luis</code>, <code>sean</code>, or <code>miguel</code>). The temporary first-use password is <strong>123</strong>. Change it to your own private password when prompted, before using the board; this lets the history identify the teammate who made each change. The board is for project tasks only and is separate from learners&#39; offline game profiles.</p><h2 id="current-focus-and-approval-gate">Current focus and approval gate<a class="header-anchor" href="#current-focus-and-approval-gate" aria-label="Link to this section">​</a></h2><p>The November 11 reconciliation leaves <strong>36 active deliverable cards</strong>, with 78 superseded cards archived recoverably and six necessary cards added. The live board holds current status and named history; its retained encyclopedia card was restored and the final set verified against the backup. The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">current GDD</a> defines 39 ordered lessons, nine distinct minigames and a required 13-question review per world, with mistakes retried until all answers are correct. Consolidated deliverables retain their required checks and explicit role handoffs.</p><p><strong>Documentation and necessary preparation are authorized; game development requires final owner approval.</strong> An implementation card&#39;s presence, date or retained In Progress status does not grant that approval. The <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">task plan</a> contains provisional rebaselined windows for review, not automatic start dates or delivery guarantees. <strong>Pre-final remains November 21, 2026.</strong> The November 10 community session is a past scheduled event whose actual outcome remains unverified. Preserve integration, device QA, manuscript and rehearsal work when reviewing dates.</p><h2 id="update-a-card">Update a card<a class="header-anchor" href="#update-a-card" aria-label="Link to this section">​</a></h2><ul><li>Use the Board view for cards or Timeline for the Gantt schedule. The colors identify work lanes; the card name and owner show what the task is about. Card names describe the work rather than relying on task codes.</li><li>An <strong>Overdue</strong> badge appears on an unfinished card starting the day after its finish date in Manila time. Timeline rows show the same label and rose bars. Marking the card Done or moving its finish date clears the cue; it does not change the card&#39;s status or schedule by itself.</li><li>Select a card to open it; use its separate move grip when you want to drag it. In a card, add checklist steps, tick them off, or remove them as the work changes. You can read the full description, completion check, dates, prerequisites, history, evidence and reference links. Fields grow with their contents; the page can scroll when a long card needs more space.</li><li>Move the card when work starts, is ready for review, or is finished. Mark it Done only when the card&#39;s check is met.</li><li>Use <strong>Evidence and updates</strong> for what changed, what remains, and any blocker. Put each shareable source, build, image, or review URL in <strong>Reference links</strong> on its own <code>https://</code> line. Those links also go to the public GitHub issue copy, so never paste a signed/private link, login token, learner name, or participant record. Save the card to add the links to its history and linked GitHub record.</li><li>Each card has one role lane and one owner. If someone in a different role needs to continue the work, create a separate card with a clear handoff instead of adding a second owner.</li></ul><h2 id="archive-and-history">Archive and history<a class="header-anchor" href="#archive-and-history" aria-label="Link to this section">​</a></h2><p>Choose <strong>Archive task</strong> when work should leave the active board. Archiving hides it from the working board and timeline but keeps its record and history available in <strong>Archive</strong>. Restore it if needed. Cards are not permanently deleted.</p><p>Superseded economy work, teacher services, exports and standalone Wordle/BlockMatch are outside current game scope. Archive their cards while preserving evidence and history; do not mark obsolete work Done merely to remove it from view. Completed earlier work remains part of the record without proving acceptance of the new design.</p><p>The History tab records the account that changed a card, the change, the board area, and the server time. Change your initial shared password immediately so the person recorded in history is meaningful. Do not put learner names or participant records in board cards; use synthetic or approved anonymous evidence.</p><p>Trello is retired. Make changes in this board; the linked GitHub issue is an automatically updated copy. See <a href="/Chainy-Docs/content/docs/team-delegation.html">role ownership</a>, <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">task plan</a>, and <a href="/Chainy-Docs/content/docs/project-baseline.html">project baseline</a>.</p></div>',1)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
